function localDayKey(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`;}
function dayStart(key){const [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d,0,0,0,0);}
function selectedTimeRange(){const now=new Date();if(selectedDateMode==='all')return {from:'',to:'',label:'All dates',live:false};if(selectedDateMode==='live')return {from:new Date(now.getTime()-86400000).toISOString(),to:'',label:'LIVE · 24h',live:true};let key='';if(selectedDateMode==='today')key=localDayKey(now);else if(selectedDateMode==='yesterday'){const d=new Date(now);d.setDate(d.getDate()-1);key=localDayKey(d);}else if(selectedDateMode.startsWith('day:'))key=selectedDateMode.slice(4);if(!key)return {from:'',to:'',label:'All dates',live:false};const from=dayStart(key),to=new Date(from);to.setDate(to.getDate()+1);const today=localDayKey(now),yd=new Date(now);yd.setDate(yd.getDate()-1);const label=key===today?'Today':key===localDayKey(yd)?'Yesterday':from.toLocaleDateString();return {from:from.toISOString(),to:to.toISOString(),label,live:false};}
function rangeQuery(includeTarget=true){const tr=selectedTimeRange(),q=new URLSearchParams();if(selectedDateMode==='all')q.set('all','1');if(tr.from)q.set('from',tr.from);if(tr.to)q.set('to',tr.to);if(includeTarget&&selectedTarget)q.set('target',selectedTarget);const x=q.toString();return x?'?'+x:'';}
