function renderChart(events){ const svg=$('activityChart'),bins=30,arr=Array(bins).fill(0),tr=selectedTimeRange(),now=Date.now();let startMs,endMs;if(tr.from)startMs=new Date(tr.from).getTime();if(tr.to)endMs=new Date(tr.to).getTime();if(!endMs)endMs=now;if(!startMs){const times=(events||[]).map(e=>new Date(e.at).getTime()).filter(Number.isFinite);startMs=times.length?Math.min(...times):endMs-86400000;}if(endMs<=startMs)endMs=startMs+1;const span=endMs-startMs;(events||[]).forEach(e=>{const t=new Date(e.at).getTime();if(t>=startMs&&t<endMs){const idx=Math.min(bins-1,Math.max(0,Math.floor((t-startMs)/span*bins)));arr[idx]++;}});const max=Math.max(1,...arr),w=600,h=150,pts=arr.map((v,i)=>`${i/(bins-1)*w},${h-10-v/max*(h-25)}`).join(' ');svg.innerHTML=`<line class="gridline" x1="0" y1="40" x2="600" y2="40"/><line class="gridline" x1="0" y1="80" x2="600" y2="80"/><line class="gridline" x1="0" y1="120" x2="600" y2="120"/><polygon class="chart-fill" points="0,150 ${pts} 600,150"/><polyline class="chart-line" points="${pts}"/>`;}

