function sshTranscriptStepHTML(e,s){const title=`${new Date(e.at).toLocaleTimeString()} · ${esc(e.type)}`,attr=`data-ssh-transcript-event="${esc(e.id||'')}"`;if(e.type==='command'||e.type==='exec')return `<div class="transcript-step" ${attr}><small>${title} · ${esc(e.command_family||'other')}</small><b>${esc((e.username||s.username||'user')+'@'+(e.cwd||'/')+' $ '+(e.command||''))}</b>${e.output?`<pre>${esc(e.output)}</pre>`:''}</div>`;return `<div class="transcript-step" ${attr}><small>${title}</small><span>${esc(e.message||e.auth_method||e.type)}</span></div>`;}
function sshSessionStatus(s){if(s&&s.active)return {label:'LIVE',cls:'live'};const t=s&&s.disconnected_at?Date.now()-new Date(s.disconnected_at).getTime():Infinity;if(t<=10000)return {label:`LEFT ${Math.max(0,Math.floor(t/1000))}s`,cls:'left'};return {label:'ENDED',cls:'ended'};}
