function appendOpenSSHEvent(e){if(!openSSHSessionId||e.session_id!==openSSHSessionId||!$('sshDrawer').classList.contains('open'))return;const atBottom=sshDrawerAtBottom();if(!openSSHSessionData)return;openSSHSessionData.events=openSSHSessionData.events||[];if(openSSHSessionData.events.some(x=>x.id===e.id))return;openSSHSessionData.events.push(e);$('sshTranscript').insertAdjacentHTML('beforeend',sshTranscriptStepHTML(e,openSSHSessionData.session));const s=openSSHSessionData.session;s.last_seen=e.at;if(e.username)s.username=e.username;if(e.client_version)s.client_version=e.client_version;if(e.cwd)s.current_dir=e.cwd;if(e.depth>s.depth)s.depth=e.depth;if(e.command&&(e.type==='command'||e.type==='exec')){s.current_command=e.command;s.command_count=(s.command_count||0)+1;}if(e.type==='auth')s.auth_attempts=(s.auth_attempts||0)+1;if(e.auth_accepted)s.auth_accepted=true;if(e.type==='connect'||e.type==='shell')s.active=true;if(['disconnect','handshake_error','limit'].includes(e.type)){s.active=false;s.disconnected_at=e.at;s.current_command='';}updateSSHDrawerStatus(s);if(atBottom){requestAnimationFrame(()=>{$('sshDrawer').scrollTop=$('sshDrawer').scrollHeight;});}else{sshDrawerPending++;const b=$('sshNewEvents');b.hidden=false;b.textContent=`${sshDrawerPending} new live event${sshDrawerPending===1?'':'s'} ↓`;}clearTimeout(sshDrawerMetaTimer);sshDrawerMetaTimer=setTimeout(()=>refreshOpenSSHSessionMeta(),450);}
