function applySSHLiveFeedEvent(e){let x=sshLiveFeedState.get(e.session_id);if(!x)x={session:{id:e.session_id,ip:e.ip,country:e.country||'',username:e.username||'',client_version:e.client_version||'',first_seen:e.at,last_seen:e.at,active:e.type!=='disconnect'&&e.type!=='handshake_error'&&e.type!=='limit',depth:e.depth||0,command_count:0,last_action:e.command||e.message||e.type},events:[]};const ss=x.session;ss.ip=e.ip||ss.ip;ss.country=e.country||ss.country;ss.username=e.username||ss.username;ss.client_version=e.client_version||ss.client_version;ss.last_seen=e.at;ss.depth=Math.max(ss.depth||0,e.depth||0);ss.last_action=e.command||e.message||e.type;if(e.command&&(e.type==='command'||e.type==='exec'))ss.command_count=(ss.command_count||0)+1;if(e.type==='connect'||e.type==='shell')ss.active=true;if(['disconnect','handshake_error','limit'].includes(e.type)){ss.active=false;ss.disconnected_at=e.at;}x.events.push(e);x.events=x.events.slice(-10);sshLiveFeedState.set(e.session_id,x);renderSSHLiveFeed();}
