function appendOpenWebEvent(e){if(!openWebSessionId||e.session_id!==openWebSessionId||!$('drawer').classList.contains('open'))return;const atBottom=httpDrawerAtBottom();if(!openWebSessionData)return;openWebSessionData.events=openWebSessionData.events||[];if(openWebSessionData.events.some(x=>x.id===e.id))return;openWebSessionData.events.push(e);$('httpTimeline').insertAdjacentHTML('beforeend',httpTimelineStepHTML(e));const ss=openWebSessionData.session;ss.last_seen=e.at;ss.current_path=e.path||ss.current_path;ss.last_method=e.method||ss.last_method;ss.last_status=e.status||ss.last_status;ss.request_count=Math.max(ss.request_count||0,e.session_requests||0);ss.visit_count=Math.max(ss.visit_count||1,e.session_visits||1);ss.depth=Math.max(ss.depth||0,e.depth||0);ss.loop=Math.max(ss.loop||0,e.loop||0);ss.frustration=Math.max(ss.frustration||0,e.frustration||0);ss.risk_score=Math.max(ss.risk_score||0,e.risk_score||0);ss.automation_score=e.automation_score??ss.automation_score;ss.classification=e.classification||ss.classification;ss.actor=e.actor||ss.actor;ss.persona=e.persona||ss.persona;fillWebSessionMeta(ss);if(atBottom){requestAnimationFrame(()=>{$('drawer').scrollTop=$('drawer').scrollHeight;});}else{httpDrawerPending++;const b=$('httpNewEvents');b.hidden=false;b.textContent=`${httpDrawerPending} new live request${httpDrawerPending===1?'':'s'} ↓`;}clearTimeout(httpDrawerMetaTimer);httpDrawerMetaTimer=setTimeout(()=>refreshOpenWebSessionMeta(),450);}
