function renderSSHLiveFeed(){const now=Date.now(),all=[...sshLiveFeedState.values()].filter(x=>x.session.active||(!x.session.disconnected_at?false:now-new Date(x.session.disconnected_at).getTime()<=10000)).sort((a,b)=>new Date(b.session.last_seen)-new Date(a.session.last_seen));const live=all.filter(x=>x.session.active).length,left=all.length-live;const summary=`${live} live · ${left} recently left`;if($('sshLiveFeedSummary'))$('sshLiveFeedSummary').textContent=summary;if($('sshLiveFeedLauncherSummary'))$('sshLiveFeedLauncherSummary').textContent=`${live} live`;if(!$('sshLiveFeed'))return;const items=all.filter(x=>sshLiveFeedFilter==='all'||(sshLiveFeedFilter==='live'&&x.session.active)||(sshLiveFeedFilter==='left'&&!x.session.active));$('sshLiveFeed').innerHTML=items.map(x=>{const s=x.session,st=sshSessionStatus(s);return `<article class="ssh-live-card ${st.cls}" data-ssh-id="${esc(s.id)}"><div class="ssh-live-card-head"><div><b>${esc(s.ip||'—')}</b><span>${esc(s.username||'—')} · ${esc(short(sshClientLabel(s.client_version),28))} · D${s.depth||0}</span></div><span class="ssh-live-state ${st.cls}">${esc(st.label)}</span></div><div class="ssh-live-card-events">${(x.events||[]).map(e=>`<div><time>${new Date(e.at).toLocaleTimeString()}</time><span>${esc((e.type||'').toUpperCase())}</span><b title="${esc(e.command||e.message||e.type)}">${esc(short(e.command||e.message||e.type,70))}</b></div>`).join('')||'<small>No retained activity yet.</small>'}</div><div class="ssh-live-card-foot"><span>${esc(short(s.last_action||'waiting for activity',68))}</span><button type="button">View session</button></div></article>`}).join('')||`<small>No ${sshLiveFeedFilter==='live'?'live':sshLiveFeedFilter==='left'?'recently left':'live SSH'} sessions right now.</small>`;document.querySelectorAll('#sshLiveFeed [data-ssh-id]').forEach(card=>{card.querySelector('button').onclick=()=>openSSHSession(card.dataset.sshId);});if(sshLiveFeedFollow)requestAnimationFrame(()=>document.querySelectorAll('#sshLiveFeed .ssh-live-card-events').forEach(box=>{box.scrollTop=box.scrollHeight;}));}

function renderSSHHighlights(){
  const body=$('sshHighlightsBody');if(!body)return;
  body.innerHTML=sshHighlights.map(h=>{const tags=(h.tags||[]).map(t=>`<span class="ssh-highlight-tag">${esc(t)}</span>`).join('');return `<tr data-ssh-highlight-id="${esc(h.session_id)}"><td>${esc(dt(h.at))}</td><td>${esc(h.ip||'—')}</td><td>${esc(h.country||'—')}</td><td><span class="highlight-rating ${esc(h.rating)}">${esc(h.rating)}</span></td><td><span class="ssh-highlight-score ${esc(h.rating)}">${h.score}/100</span></td><td><span class="ssh-highlight-title" title="${esc(h.title)}">${esc(h.title)}</span>${tags?`<span class="ssh-highlight-tags">${tags}</span>`:''}<span class="ssh-highlight-reason" title="${esc(h.reason)}">${esc(h.reason)}</span></td><td>${h.commands||0}</td><td>${esc(duration((h.duration_seconds||0)*1000))}</td><td>${h.depth||0}</td></tr>`;}).join('')||'<tr><td colspan="9"><small>No SSH highlights match this rating yet.</small></td></tr>';
  $('sshHighlightsCount').textContent=`${sshHighlights.length} loaded · authenticated + noteworthy`;
  document.querySelectorAll('#sshHighlightsBody [data-ssh-highlight-id]').forEach(tr=>tr.onclick=()=>openSSHSession(tr.dataset.sshHighlightId));
}
async function loadSSHHighlights(reset=false){
  if(sshHighlightLoading||(!reset&&sshHighlightExhausted))return;
  sshHighlightLoading=true;if($('sshHighlightsLoading'))$('sshHighlightsLoading').hidden=false;
  if(reset){sshHighlights=[];sshHighlightNext='';sshHighlightExhausted=false;renderSSHHighlights();}
  try{let url='/api/ssh/highlights?limit=20&rating='+encodeURIComponent(sshHighlightFilter);if(!reset&&sshHighlightNext)url+='&before='+encodeURIComponent(sshHighlightNext);const page=await api(url),items=page.items||[];const known=new Set(sshHighlights.map(x=>x.session_id));for(const h of items)if(!known.has(h.session_id)){sshHighlights.push(h);known.add(h.session_id)}sshHighlightNext=page.next_before||'';sshHighlightExhausted=!sshHighlightNext||items.length===0;renderSSHHighlights();}catch(e){console.error(e)}finally{sshHighlightLoading=false;if($('sshHighlightsLoading'))$('sshHighlightsLoading').hidden=true;}
}
function setSSHHighlightFilter(filter){sshHighlightFilter=filter;document.querySelectorAll('#sshHighlightFilters [data-highlight-filter]').forEach(b=>b.classList.toggle('active',b.dataset.highlightFilter===filter));loadSSHHighlights(true);}

let trustedSettings={manual:[],proxy:[]};
async function loadTrustedSettings(){try{trustedSettings=await api('/api/settings/trusted-domains');renderTrustedSettings();}catch(e){console.error(e)}}
function renderTrustedSettings(){const manual=(trustedSettings.manual||[]).map(x=>x.domain).sort();$('trustedDomainsInput').value=manual.join('\n');const proxy=trustedSettings.proxy||[];$('proxyTrustedDomains').innerHTML=proxy.map(x=>`<div class="trusted-domain-row"><b>${esc(x.domain)}</b><span>${esc(x.integration||'verified proxy')}</span></div>`).join('')||'<small>No proxy-trusted targets yet.</small>';}
async function openSettings(){await loadTrustedSettings();$('settingsModal').classList.add('open');$('settingsBackdrop').classList.add('open');$('settingsModal').setAttribute('aria-hidden','false');$('settingsBackdrop').setAttribute('aria-hidden','false');document.body.classList.add('overlay-scroll-lock');$('settingsStatus').textContent='';}
function closeSettings(){$('settingsModal').classList.remove('open');$('settingsBackdrop').classList.remove('open');$('settingsModal').setAttribute('aria-hidden','true');$('settingsBackdrop').setAttribute('aria-hidden','true');syncOverlayBodyLock();}
function openHelp(){$('helpModal').classList.add('open');$('helpBackdrop').classList.add('open');$('helpModal').setAttribute('aria-hidden','false');$('helpBackdrop').setAttribute('aria-hidden','false');syncOverlayBodyLock();}
function closeHelp(){$('helpModal').classList.remove('open');$('helpBackdrop').classList.remove('open');$('helpModal').setAttribute('aria-hidden','true');$('helpBackdrop').setAttribute('aria-hidden','true');syncOverlayBodyLock();}
async function saveTrustedSettings(){
  const domains=$('trustedDomainsInput').value.split(/\r?\n|,/).map(x=>x.trim()).filter(Boolean),button=$('saveSettings'),original='Save trusted domains';
  clearTimeout(trustedSaveFeedbackTimer);trustedSaveFeedbackTimer=0;
  button.disabled=true;button.classList.remove('saved');button.classList.add('saving');button.textContent='Saving…';$('settingsStatus').textContent='';
  try{
    const r=await fetch('/api/settings/trusted-domains',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({domains})});
    if(!r.ok){const msg=(await r.text()).trim();throw new Error(msg||String(r.status));}
    trustedSettings=await r.json();renderTrustedSettings();selectedTarget='';await refresh();
    button.classList.remove('saving');button.classList.add('saved');button.textContent='Gespeichert ✓';button.disabled=false;
    trustedSaveFeedbackTimer=setTimeout(()=>{button.classList.remove('saved');button.textContent=original;trustedSaveFeedbackTimer=0;},5000);
  }catch(e){button.classList.remove('saving','saved');button.textContent=original;button.disabled=false;$('settingsStatus').textContent=e.message||'save failed';console.error(e)}
}

function openSSHLiveFeed(){const modal=$('sshLiveFeedModal'),backdrop=$('sshLiveFeedBackdrop');if(!modal||!backdrop)return;modal.classList.add('open');backdrop.classList.add('open');modal.setAttribute('aria-hidden','false');backdrop.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');syncOverlayBodyLock();renderSSHLiveFeed();}
function closeSSHLiveFeed(){const modal=$('sshLiveFeedModal'),backdrop=$('sshLiveFeedBackdrop');if(!modal||!backdrop)return;modal.classList.remove('open');backdrop.classList.remove('open');modal.setAttribute('aria-hidden','true');backdrop.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');syncOverlayBodyLock();}
function setSSHLiveFeedFilter(filter){sshLiveFeedFilter=filter;document.querySelectorAll('#sshLiveFeedFilters [data-feed-filter]').forEach(b=>b.classList.toggle('active',b.dataset.feedFilter===filter));renderSSHLiveFeed();}
function toggleSSHLiveFollow(){sshLiveFeedFollow=!sshLiveFeedFollow;const b=$('sshLiveFollow');b.classList.toggle('active',sshLiveFeedFollow);b.setAttribute('aria-pressed',sshLiveFeedFollow?'true':'false');b.textContent=sshLiveFeedFollow?'● Live follow':'○ Follow paused';if(sshLiveFeedFollow)renderSSHLiveFeed();}
function syncOverlayBodyLock(){const overlayOpen=[$('sshLiveFeedModal'),$('settingsModal'),$('helpModal'),$('drawer'),$('sshDrawer'),$('actorDrawer')].some(el=>el&&el.classList.contains('open'));document.body.classList.toggle('overlay-scroll-lock',overlayOpen);}function closeDrawer(){openWebSessionId='';openWebSessionData=null;httpDrawerPending=0;if($('httpNewEvents'))$('httpNewEvents').hidden=true;$('drawer').classList.remove('open');$('drawer').setAttribute('aria-hidden','true');if(!$('sshDrawer').classList.contains('open')&&!$('actorDrawer').classList.contains('open'))$('shade').classList.remove('open');syncOverlayBodyLock()}function closeSSHDrawer(){openSSHSessionId='';openSSHSessionData=null;sshDrawerPending=0;$('sshNewEvents').hidden=true;$('sshDrawer').classList.remove('open');$('sshDrawer').setAttribute('aria-hidden','true');if(!$('drawer').classList.contains('open')&&!$('actorDrawer').classList.contains('open'))$('shade').classList.remove('open');syncOverlayBodyLock()}function closeActorDrawer(){$('actorDrawer').classList.remove('open');$('actorDrawer').setAttribute('aria-hidden','true');if(!$('drawer').classList.contains('open')&&!$('sshDrawer').classList.contains('open'))$('shade').classList.remove('open');syncOverlayBodyLock()}function closeAllDrawers(){closeDrawer();closeSSHDrawer();closeActorDrawer();$('shade').classList.remove('open');syncOverlayBodyLock()}$('closeDrawer').onclick=closeDrawer;$('closeSSHDrawer').onclick=closeSSHDrawer;$('closeActorDrawer').onclick=closeActorDrawer;$('shade').onclick=closeAllDrawers;
let httpLiveSource=null,sshLiveSource=null;
function connect(){if(httpLiveSource||!selectedTimeRange().live)return;const es=new EventSource('/api/live/events');httpLiveSource=es;es.addEventListener('request',ev=>{try{const e=JSON.parse(ev.data);appendOpenWebEvent(e);if(!selectedTimeRange().live||!eventMatchesSelectedTarget(e))return;const box=$('events');box.insertAdjacentHTML('afterbegin',eventHTML(e));while(box.children.length>lazyLimits.httpEvents)box.lastElementChild.remove();recentEvents.unshift(e);recentEvents=recentEvents.slice(0,Math.max(240,lazyLimits.httpEvents));renderChart(recentEvents);setTimeout(refreshOverviewOnly,120);}catch(err){}});es.onerror=()=>{};}
function connectSSH(){if(sshLiveSource||!selectedTimeRange().live)return;const es=new EventSource('/api/live/ssh');sshLiveSource=es;es.addEventListener('ssh',ev=>{try{if(!selectedTimeRange().live)return;const e=JSON.parse(ev.data),box=$('sshEvents');box.insertAdjacentHTML('afterbegin',sshEventHTML(e));while(box.children.length>lazyLimits.sshEvents)box.lastElementChild.remove();sshRecentEvents.unshift(e);sshRecentEvents=sshRecentEvents.slice(0,Math.max(160,lazyLimits.sshEvents));applySSHLiveFeedEvent(e);appendOpenSSHEvent(e);setTimeout(refreshSSHOnly,120);}catch(err){}});es.onerror=()=>{};}
function syncLiveStreams(){const live=selectedTimeRange().live;if(live){connect();connectSSH();return;}if(httpLiveSource){httpLiveSource.close();httpLiveSource=null;}if(sshLiveSource){sshLiveSource.close();sshLiveSource=null;}}
async function refreshSSHOnly(){try{const nrq=rangeQuery(false),namp=rangeAmp(false);const [o,s]=await Promise.all([api('/api/ssh/overview'+nrq),api('/api/ssh/sessions?limit='+lazyLimits.sshSessions+namp)]);renderSSHOverview(o);renderSSHSessions(s);}catch(e){}}
async function refreshOverviewOnly(){try{const rq=rangeQuery(true),amp=rangeAmp(true);const [o,s]=await Promise.all([api('/api/overview'+rq),api('/api/sessions?limit='+lazyLimits.sessions+amp)]);renderOverview(o);renderSessions(s);}catch(e){}}
function resetGlobalLazy(){for(const k of Object.keys(lazyLimits))lazyLimits[k]=20;for(const k of Object.keys(lazyExhausted))delete lazyExhausted[k];}
function noteLoaded(key,count){lazyExhausted[key]=count<lazyLimits[key];}
function lazyEndpoint(key){
  const amp=rangeAmp(true),namp=rangeAmp(false);
  switch(key){
    case 'sessions':return '/api/sessions?limit='+lazyLimits[key]+amp;
    case 'history':return '/api/history?limit='+lazyLimits[key]+amp;
    case 'unknown':return '/api/unknown-paths?limit='+lazyLimits[key]+namp;
    case 'recentPaths':return '/api/recent-paths?limit='+lazyLimits[key]+namp;
    case 'catchAll':return '/api/catchall-hosts?limit='+lazyLimits[key]+namp;
    case 'knownProbes':return '/api/known-probes?limit='+lazyLimits[key]+namp;
    case 'sshSessions':return '/api/ssh/sessions?limit='+lazyLimits[key]+namp;
    case 'sshHistory':return '/api/ssh/history?limit='+lazyLimits[key]+namp;
    case 'sshEvents':return '/api/ssh/events?limit='+lazyLimits[key]+namp;
    case 'actors':return '/api/actors?limit='+lazyLimits[key]+namp;
    case 'bursts':return '/api/bursts?limit='+lazyLimits[key]+namp;
    case 'intel':return '/api/intelligence?limit='+lazyLimits[key]+namp;
    case 'httpEvents':return '/api/events?limit='+lazyLimits[key]+amp;
  }
  return '';
}
function applyLazyRows(key,data){
  let count=Array.isArray(data)?data.length:((data&&data.hosts)||[]).length;
  switch(key){
    case 'sessions':renderSessions(data);break;
    case 'history':historyRows=data;renderHistory();break;
    case 'unknown':renderUnknown(data);break;
    case 'recentPaths':renderRecentPaths(data);break;
    case 'catchAll':renderCatchAll(data);break;
    case 'knownProbes':renderKnownProbes(data);break;
    case 'sshSessions':renderSSHSessions(data);break;
    case 'sshHistory':renderSSHHistory(data);break;
    case 'sshEvents':sshRecentEvents=data;renderSSHEvents(data);break;
    case 'actors':renderActors(data);break;
    case 'bursts':renderBursts(data);break;
    case 'intel':renderIntel(data);break;
    case 'httpEvents':recentEvents=data;renderEvents(recentEvents);count=data.length;break;
  }
  return count;
}

async function loadNext(key,box){
  if(lazyLoading[key]||lazyExhausted[key])return;
  const url=lazyEndpoint(key);if(!url)return;
  lazyLoading[key]=true;
  const old=lazyLimits[key],scrollTop=box?box.scrollTop:0;lazyLimits[key]=Math.min(old+lazyStep,1000);
  if(lazyLimits[key]===old){lazyLoading[key]=false;lazyExhausted[key]=true;return;}
  try{const data=await api(lazyEndpoint(key)),count=applyLazyRows(key,data);if(count<lazyLimits[key])lazyExhausted[key]=true;if(box)requestAnimationFrame(()=>{box.scrollTop=scrollTop;});}catch(e){lazyLimits[key]=old;console.error(e)}finally{lazyLoading[key]=false;}
}

function bindLazyScroll(id,key,direct=false){
  const node=$(id);if(!node)return;const box=direct?node:node.closest('.table-wrap');if(!box)return;
  box.addEventListener('scroll',()=>{if(box.scrollTop+box.clientHeight>=box.scrollHeight-48)loadNext(key,box);},{passive:true});
}
function initLazyScroll(){
  [['sessionsBody','sessions'],['historyBody','history'],['actorsBody','actors'],['burstsBody','bursts'],['intelBody','intel'],['sshSessionsBody','sshSessions'],['sshHistoryBody','sshHistory'],['recentPathsBody','recentPaths'],['knownProbeBody','knownProbes'],['unknownBody','unknown'],['catchAllBody','catchAll']].forEach(([id,key])=>bindLazyScroll(id,key));
  bindLazyScroll('events','httpEvents',true);bindLazyScroll('sshEvents','sshEvents',true);
}
$('sshEvents').addEventListener('click',ev=>{const jump=ev.target.closest('.ssh-jump[data-ssh-session]');if(!jump)return;ev.preventDefault();openSSHSession(jump.dataset.sshSession,jump.dataset.sshEvent||'');});
$('sshHighlightsScroll').addEventListener('scroll',()=>{const box=$('sshHighlightsScroll');if(box.scrollTop+box.clientHeight>=box.scrollHeight-64)loadSSHHighlights(false);},{passive:true});$('sshHighlightFilters').addEventListener('click',ev=>{const b=ev.target.closest('[data-highlight-filter]');if(b)setSSHHighlightFilter(b.dataset.highlightFilter);});
$('openSSHLiveFeed').onclick=openSSHLiveFeed;$('closeSSHLiveFeed').onclick=closeSSHLiveFeed;$('sshLiveFeedBackdrop').onclick=closeSSHLiveFeed;$('sshLiveFollow').onclick=toggleSSHLiveFollow;$('sshLiveFeedFilters').addEventListener('click',ev=>{const b=ev.target.closest('[data-feed-filter]');if(b)setSSHLiveFeedFilter(b.dataset.feedFilter);});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&$('helpModal').classList.contains('open')){closeHelp();return;}if(ev.key==='Escape'&&$('settingsModal').classList.contains('open')){closeSettings();return;}if(ev.key==='Escape'&&$('sshDrawer').classList.contains('open')){closeSSHDrawer();return;}if(ev.key==='Escape'&&$('sshLiveFeedModal').classList.contains('open'))closeSSHLiveFeed();});
$('openSettings').onclick=openSettings;$('closeSettings').onclick=closeSettings;$('settingsBackdrop').onclick=closeSettings;$('saveSettings').onclick=saveTrustedSettings;$('openHelp').onclick=openHelp;$('closeHelp').onclick=closeHelp;$('helpBackdrop').onclick=closeHelp;$('historySearch').addEventListener('input',renderHistory);$('targetFilter').addEventListener('change',()=>{selectedTarget=$('targetFilter').value;resetGlobalLazy();refresh();});$('dateFilter').addEventListener('change',()=>{selectedDateMode=$('dateFilter').value;resetGlobalLazy();updateRangeLabels();syncLiveStreams();refresh();loadSSHHighlights(true);});
setInterval(()=>{$('clock').textContent=new Date().toLocaleTimeString()},1000);setInterval(refresh,10000);initLazyScroll();loadInfo();loadAvailableDays().then(()=>{syncLiveStreams();refresh();});loadSSHHighlights(true);

$('httpNewEvents').onclick=followHTTPDrawer;$('sshNewEvents').onclick=followSSHDrawer;setInterval(()=>{if($('sshLiveFeed'))renderSSHLiveFeed();if(openSSHSessionData)updateSSHDrawerStatus(openSSHSessionData.session);},1000);
